INSERT INTO `question_bank` VALUES (1,1,'Arrays','What is the time complexity of accessing an array element by index?','O(1)','O(log n)','O(n)','O(n log n)','A','2026-11-05 11:45:06','2026-11-05 11:45:06'),(2,1,'Arrays','In a zero-indexed array, what is the index of the fifth element?','4','5','3','6','A','2026-11-05 11:45:06','2026-11-05 11:45:06'),(3,1,'Arrays','Which operation usually requires shifting elements in an array?','Insertion at the beginning','Access by index','Reading the last element','Updating an existing index','A','2026-11-05 11:45:06','2026-11-05 11:45:06'),(4,1,'Arrays','What is the time complexity of linear search in the worst case?','O(n)','O(1)','O(log n)','O(n log n)','A','2026-11-05 11:45:06','2026-11-05 11:45:06'),(5,1,'Arrays','Which condition must hold for binary search to work correctly on an array?','The array must be sorted','The array must contain unique values','The array must have even length','The array must contain positive values','A','2026-11-05 11:45:06','2026-11-05 11:45:06'),(6,1,'Linked Lists','Which pointer is stored in a singly linked-list node?','A pointer to the next node','Pointers to both previous and next nodes','An index of the node','A pointer to the root','A','2026-11-05 11:45:06','2026-11-05 11:45:06'),(7,1,'Linked Lists','What is the time complexity of inserting a node at the head of a singly linked list?','O(1)','O(log n)','O(n)','O(n log n)','A','2026-11-05 11:45:06','2026-11-05 11:45:06'),(8,1,'Linked Lists','Which linked list allows traversal in both directions?','Doubly linked list','Singly linked list','Circular singly linked list','Unordered array','A','2026-11-05 11:45:06','2026-11-05 11:45:06'),(9,1,'Linked Lists','In a circular linked list, the last node points to which node?','The first node','NULL','The middle node','A newly allocated node','A','2026-11-05 11:45:06','2026-11-05 11:45:06'),(10,1,'Linked Lists','Which data structure is commonly used to detect a cycle in a linked list efficiently?','Flo