INSERT INTO `results` VALUES (2,4,9,3,0,10,0.00,'F','fail','<div style=\"font-family:system-ui,-apple-system,sans-serif;line-height:1.6\">\n    <div style=\"text-align:center;margin-bottom:20px\">\n        <div style=\"font-size:2.5rem\">💪</div>\n        <h3 style=\"margin:8px 0 4px;font-size:1.25rem\">Keep Pushing Forward</h3>\n        <p style=\"color:#6b7280;font-size:0.95rem;margin:0\">This is a challenging journey, and every attempt is a learning opportunity. Focus on building your foundational knowledge step by step.</p>\n    </div>\n\n    <div style=\"display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-bottom:20px;text-align:center\">\n        <div style=\"background:#f0fdf4;border-radius:8px;padding:12px\"><div style=\"font-size:1.5rem;font-weight:800;color:#10b981\">0</div><div style=\"font-size:0.8rem;color:#6b7280\">Correct</div></div>\n        <div style=\"background:#fef2f2;border-radius:8px;padding:12px\"><div style=\"font-size:1.5rem;font-weight:800;color:#ef4444\">10</div><div style=\"font-size:0.8rem;color:#6b7280\">Incorrect</div></div>\n        <div style=\"background:#fffbeb;border-radius:8px;padding:12px\"><div style=\"font-size:1.5rem;font-weight:800;color:#f59e0b\">0</div><div style=\"font-size:0.8rem;color:#6b7280\">Unanswered</div></div>\n        <div style=\"background:#eff6ff;border-radius:8px;padding:12px\"><div style=\"font-size:1.5rem;font-weight:800;color:#3b82f6\">0%</div><div style=\"font-size:0.8rem;color:#6b7280\">Score</div></div>\n    </div>\n\n    <div style=\"margin-bottom:20px\">\n        <h4 style=\"margin:0 0 10px;font-size:1rem\">✅ Strengths</h4>\n        <ul style=\"margin:0;padding-left:20px;font-size:0.9rem\"><li style=\"margin-bottom:6px\">You attempted <strong>every question</strong> — great time management and confidence!</li></ul>\n    </div>\n\n    <div style=\"margin-bottom:20px\">\n        <h4 style=\"margin:0 0 10px;font-size:1rem\">🔍 Areas for Improvement</h4>\n        <ul style=\"margin:0;padding-left:20px;font-size:0.9rem\"><li style=\"margin-bottom:6px\">Performance on medium-difficulty questions was below average (<strong>0/10</strong>). This is where the biggest gains can be made.</li><li style=\"margin-bottom:6px\">More than half of your attempted answers were incorrect. Focus on understanding concepts rather than memorizing answers.</li></ul>\n    </div>\n\n    <div style=\"margin-bottom:20px\">\n        <h4 style=\"margin:0 0 10px;font-size:1rem\">📊 Difficulty Analysis</h4>\n        <div style=\"margin-bottom:12px\"><div style=\"display:flex;justify-content:space-between;font-size:0.9rem\"><strong>Medium</strong><span>0/10 (0%)</span></div><div style=\"background:#e5e7eb;border-radius:99px;height:10px;margin-top:4px\"><div style=\"background:#f59e0b;width:0%;border-radius:99px;height:10px;min-width:4px\"></div></div></div>\n    </div>\n\n    <div style=\"margin-bottom:20px\">\n        <h4 style=\"margin:0 0 10px;font-size:1rem\">📋 Study Recommendations</h4>\n        <ul style=\"margin:0;padding-left:20px;font-size:0.9rem\"><li style=\"margin-bottom:6px\">📖 <strong>Start with the basics</strong> — re-read your textbook chapters and class notes before attempting practice questions.</li><li style=\"margin-bottom:6px\">📝 <strong>Practice medium-level problems</strong> — these form the bulk of most exams and offer the best score improvement.</li><li style=\"margin-bottom:6px\">🔄 <strong>Review mistakes</strong> — go through each incorrect answer above and understand why the correct answer is right.</li></ul>\n    </div>\n\n    \n\n    <div style=\"text-align:center;margin-top:20px;padding:16px;background:linear-gradient(135deg,#eff6ff,#f0fdf4);border-radius:8px\">\n        <p style=\"margin:0;font-size:0.95rem;color:#374151\"><strong>💡 Remember:</strong> Every exam is a stepping stone. Review your mistakes, study consistently, and you will see improvement!</p>\n    </div>\n</div>','2026-11-05 12:23:14');
